INSERT INTO "terms" ("title", "body", "position") VALUES
('Acceptance of Terms', 'By accessing this website, submitting an appointment request, or participating in any of our programs, you confirm that you have read, understood, and agreed to these Terms & Conditions. If you do not agree, please do not use our website or services.', 1),
('Appointments & Program Bookings', 'Submitting an appointment request does not guarantee a booking. All requests are subject to review and confirmation by our team. Preferred dates and time slots are accommodated wherever possible, but final scheduling depends on the availability of our teams and resources. We may contact you by phone or email to confirm venue, participant count, and other event requirements.', 2),
('Cancellations & Rescheduling', 'Please inform us as early as possible if you need to cancel or reschedule a confirmed program. Jain Social Work Ltd. reserves the right to reschedule or cancel a program due to unforeseen circumstances, safety concerns, or events beyond our control, and will make reasonable efforts to notify you in advance.', 3),
('Health & Medical Disclaimer', 'Health camps, blood donation drives, and awareness sessions are intended for screening, education, and community support only. They are not a substitute for professional medical diagnosis or treatment. Participants should consult a qualified healthcare provider for any medical concerns. Blood donation is subject to eligibility criteria determined by the attending medical professionals.', 4),
('Participant Conduct & Safety', 'Participants are expected to follow the instructions of our volunteers and trainers, especially during self-defense and physical activity sessions. Participation in such activities is voluntary and at the participant''s own risk. We reserve the right to refuse or discontinue participation for anyone whose conduct is unsafe, disruptive, or disrespectful.', 5),
('Privacy & Use of Information', 'Personal details shared through our appointment form (such as name, mobile number, and email) are used only to process your request and communicate with you about our programs. We do not sell or share your information with third parties except where required by law. Photographs or videos taken during public programs may be used for awareness and reporting purposes; please inform our team if you do not wish to be photographed.', 6),
('Limitation of Liability', 'While we take every reasonable care in organizing our programs, Jain Social Work Ltd., its members, and volunteers shall not be liable for any loss, injury, or damage arising from participation in programs or reliance on information provided on this website, to the extent permitted by law.', 7),
('Changes & Governing Law', 'We may update these Terms & Conditions from time to time, and changes take effect once published on this page. These terms are governed by the laws of India, and any disputes shall be subject to the jurisdiction of the courts in Indore, Madhya Pradesh.', 8);
